self.onInit = function () {
    var root = self.ctx.$container[0];
    var $ = function (s) { return root.querySelector(s); };
    var http = self.ctx.http;
    var custSel = $('.us-customer');
    var emailBox = $('.us-email');
    var firstBox = $('.us-first');
    var lastBox = $('.us-last');
    var groupSel = $('.us-group');
    var btn = $('.us-save');
    var msg = $('.us-msg');
    var customers = [];
    var noop = function () {};

    function show(text, ok) {
        msg.textContent = text;
        msg.className = 'dv-msg us-msg ' + (ok ? 'dv-ok' : 'dv-err');
    }

    function errText(e) {
        if (!e) { return 'Ismeretlen hiba'; }
        var m = (e.error && e.error.message) ? e.error.message : '';
        return (e.status ? e.status + ' ' : '') + (e.url ? '[' + e.url + '] ' : '') + (m || 'Ismeretlen hiba');
    }

    function getAll(url, cb) {
        var items = [];
        (function next(page) {
            http.get(url + (url.indexOf('?') >= 0 ? '&' : '?') + 'pageSize=100&page=' + page).subscribe(
                function (res) {
                    items = items.concat(res.data || []);
                    if (res.hasNext) { next(page + 1); } else { cb(null, items); }
                },
                function (e) { cb(errText(e)); }
            );
        })(0);
    }

    function selectedCustomer() { return customers[custSel.selectedIndex - 1]; }   // index 0 = placeholder

    // dashboard id saved on the customer by the "Új ügyfél" widget (0 if there is none)
    function getDashboardId(cid, cb) {
        http.get('/api/plugins/telemetry/CUSTOMER/' + cid + '/values/attributes/SERVER_SCOPE?keys=dashboardId').subscribe(
            function (arr) {
                var a = (arr || []).filter(function (x) { return x.key === 'dashboardId'; })[0];
                cb(a && a.value ? String(a.value) : null);
            },
            function () { cb(null); }
        );
    }

    // puts the user into the customer's user group (the default groups exist from the start)
    function addUserToGroup(cid, userId, groupName, cb, retried) {
        http.get('/api/entityGroups/CUSTOMER/' + cid + '/USER').subscribe(
            function (groups) {
                var g = (groups || []).filter(function (x) {
                    return String(x.name).toLowerCase() === groupName.toLowerCase();
                })[0];
                if (!g) {
                    if (!retried) {
                        setTimeout(function () { addUserToGroup(cid, userId, groupName, cb, true); }, 1500);
                        return;
                    }
                    cb('nem található a(z) "' + groupName + '" csoport (ezeket találtam: ' +
                       (groups || []).map(function (x) { return x.name; }).join(', ') + ')');
                    return;
                }
                http.post('/api/entityGroup/' + g.id.id + '/addEntities', [userId]).subscribe(
                    function () { cb(null); },
                    function (e) {
                        if (e && e.status === 200) { cb(null); return; }   // empty answer is not an error
                        cb(errText(e));
                    }
                );
            },
            function (e) { cb(errText(e)); }
        );
    }

    // load the customers
    getAll('/api/customers?sortProperty=title&sortOrder=ASC', function (err, list) {
        if (err) { show('Az ügyfelek betöltése nem sikerült: ' + err, false); return; }
        customers = list;
        custSel.textContent = '';
        var o0 = document.createElement('option');
        o0.value = '';
        o0.textContent = 'Válassz ügyfelet...';
        custSel.appendChild(o0);
        customers.forEach(function (c) {
            var o = document.createElement('option');
            o.value = c.id.id;
            o.textContent = c.title;
            custSel.appendChild(o);
        });
    });

    btn.addEventListener('click', function () {
        var c = selectedCustomer();
        var email = emailBox.value.trim();
        var first = firstBox.value.trim();
        var last = lastBox.value.trim();
        var groupName = groupSel.value;

        if (!c) { show('Válassz ügyfelet.', false); return; }
        if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) { show('Az e-mail cím érvénytelen.', false); return; }

        btn.disabled = true;
        show('Létrehozás...', true);

        getDashboardId(c.id.id, function (dashboardId) {
            var body = {
                authority: 'CUSTOMER_USER',
                customerId: { id: c.id.id, entityType: 'CUSTOMER' },
                email: email,
                firstName: first,
                lastName: last
            };
            if (dashboardId) {
                body.additionalInfo = { defaultDashboardId: dashboardId, defaultDashboardFullscreen: true };
            }

            // 1) the user (no email yet)
            http.post('/api/user?sendActivationMail=false', body).subscribe(
                function (user) {
                    var uid = user.id.id;

                    // 2) user group, otherwise the user can't log in
                    addUserToGroup(c.id.id, uid, groupName, function (gerr) {
                        if (gerr) {
                            http.delete('/api/user/' + uid).subscribe(noop, noop);
                            show('Csoport hiba: ' + gerr + ' (a felhasználó nem jött létre)', false);
                            btn.disabled = false;
                            return;
                        }

                        // 3) activation email
                        http.post('/api/user/sendActivationMail?email=' + encodeURIComponent(email), {}).subscribe(
                            function () { done(null); },
                            function (e) {
                                if (e && e.status === 200) { done(null); return; }
                                done(errText(e));
                            }
                        );

                        function done(merr) {
                            var extra = dashboardId ? '' : ' (az ügyfélnek nincs mentett dashboardja, ezért nincs alapértelmezett)';
                            if (merr) {
                                show('A felhasználó létrejött, de az aktivációs e-mail nem ment el: ' + merr, false);
                            } else {
                                show('Kész: ' + email + ' létrejött, az aktivációs e-mail elment.' + extra, true);
                            }
                            emailBox.value = '';
                            firstBox.value = '';
                            lastBox.value = '';
                            btn.disabled = false;
                        }
                    });
                },
                function (e) {
                    show('Felhasználó hiba: ' + errText(e), false);
                    btn.disabled = false;
                }
            );
        });
    });
};

self.onDestroy = function () {};

